import{_ as p,a0 as o,w as r,s as d,ao as l,I as n,x as a,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"怎样在 ubuntu 和 debian 中通过命令行管理 KVM | LCTT x X-CMD","titleTemplate":false,"description":"怎样在 ubuntu 和 debian 中通过命令行管理 KVM | LCTT (201602) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎样在 ubuntu 和 debian 中通过命令行管理 KVM | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎样在 ubuntu 和 debian 中通过命令行管理 KVM | LCTT (201602) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201602/20160104 How to use KVM from the command line on Debian or Ubuntu","title":"怎样在 ubuntu 和 debian 中通过命令行管理 KVM","tag":"201602","desc":""},"relativePath":"201602/20160104 How to use KVM from the command line on Debian or Ubuntu.md","filePath":"[post].md"}'),h={name:"201602/20160104 How to use KVM from the command line on Debian or Ubuntu.md"};function c(g,s,u,b,k,m){const i=o("Link");return r(),d("div",null,[s[18]||(s[18]=l(`<h1 id="怎样在-ubuntu-和-debian-中通过命令行管理-kvm" tabindex="-1">怎样在 ubuntu 和 debian 中通过命令行管理 KVM <a class="header-anchor" href="#怎样在-ubuntu-和-debian-中通过命令行管理-kvm" aria-label="Permalink to “怎样在 ubuntu 和 debian 中通过命令行管理 KVM”">​</a></h1><p>有很多不同的方式去管理运行在 KVM 管理程序上的虚拟机。例如，virt-manager 就是一个流行的基于图形界面的前端虚拟机管理工具。然而，如果你想要在没有图形窗口的服务器环境下使用 KVM ，那么基于图形界面的解决方案显然是行不通的。事实上，你可以单纯使用包装了 kvm 命令行脚本的命令行来管理 KVM 虚拟机。作为替代方案，你可以使用 virsh 这个容易使用的命令行程序来管理客户虚拟机。在 virsh 中，它通过和 libvirtd 服务通信来达到控制虚拟机的目的，而 libvirtd 可以控制多个不同的虚拟机管理器，包括 KVM，Xen，QEMU，LXC 和 OpenVZ。</p><p>当你想要对虚拟机的前期准备和后期管理实现自动化操作时，像 virsh 这样的命令行管理工具是非常有用的。同样，virsh 支持多个管理器也就意味着你可以通过相同的 virsh 接口去管理不同的虚拟机管理器。</p><p>在这篇文章中，我会示范<strong>怎样在 ubuntu 和 debian 上通过使用 virsh 命令行去运行 KVM</strong>。</p><h3 id="第一步-确认你的硬件平台支持虚拟化" tabindex="-1">第一步：确认你的硬件平台支持虚拟化 <a class="header-anchor" href="#第一步-确认你的硬件平台支持虚拟化" aria-label="Permalink to “第一步：确认你的硬件平台支持虚拟化”">​</a></h3><p>第一步，首先要确认你的 CPU 支持硬件虚拟化扩展（e.g.，Intel VT 或者 AMD-V)，这是 KVM 对硬件的要求。下面的命令可以检查硬件是否支持虚拟化。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ egrep &#39;(vmx|svm)&#39; --color /proc/cpuinfo</span></span></code></pre></div><p><img src="https://c2.staticflickr.com/2/1505/24050288606_758a44c4c6_c.jpg" alt=""></p><p>如果在输出中不包含 vmx 或者 svm 标识，那么就意味着你的 cpu 不支持硬件虚拟化。因此你不能在你的机器上使用 KVM 。确认了 cpu 支持 vmx 或者 svm 之后，接下来开始安装 KVM。</p><p>对于 KVM 来说，它不要求运行在拥有 64 位内核系统的主机上，但是通常我们会推荐在 64 位系统的主机上面运行 KVM。</p><h3 id="第二步-安装kvm" tabindex="-1">第二步：安装KVM <a class="header-anchor" href="#第二步-安装kvm" aria-label="Permalink to “第二步：安装KVM”">​</a></h3><p>使用 <code>apt-get</code> 安装 KVM 和相关的用户空间工具。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ sudo apt-get install qemu-kvm libvirt-bin</span></span></code></pre></div><p>安装期间，libvirtd 用户组（在 debian 上是 libvirtd-qemu 用户组）将会被创建，并且你的用户 id 将会被自动添加到该组中。这样做的目的是让你可以以一个普通用户而不是 root 用户的身份去管理虚拟机。你可以使用 <code>id</code> 命令来确认这一点，下面将会告诉你怎么去显示你的组 id：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ id &lt;your-userID&gt;</span></span></code></pre></div><p><img src="https://c2.staticflickr.com/6/5597/15432586092_64dfb867d3_c.jpg" alt=""></p><p>如果因为某些原因，libvirt（在 debian 中是 libvirt-qemu）没有在你的组 id 中被找到，你也可以手动将你自己添加到对应的组中，如下所示：</p><p>在 ubuntu 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ sudo adduser [youruserID] libvirtd</span></span></code></pre></div><p>在 debian 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ sudo adduser [youruserID] libvirt-qemu</span></span></code></pre></div><p>按照如下命令重新载入更新后的组成员关系。如果要求输入密码，那么输入你的登陆密码即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ exec su -l $USER</span></span></code></pre></div><p>这时，你应该可以以普通用户的身份去执行 virsh 了。做一个如下所示的测试，这个命令将会以列表的形式列出可用的虚拟机（当前的列表是空的）。如果你没有遇到权限问题，那意味着到目前为止一切都是正常的。</p><pre><code>$ virsh list
</code></pre><hr><pre><code> Id    Name                           State
</code></pre><hr><h3 id="第三步-配置桥接网络" tabindex="-1">第三步：配置桥接网络 <a class="header-anchor" href="#第三步-配置桥接网络" aria-label="Permalink to “第三步：配置桥接网络”">​</a></h3><p>为了使 KVM 虚拟机能够访问外部网络，一种方法是通过在 KVM 宿主机上创建 Linux 桥来实现。创建之后的桥能够将虚拟机的虚拟网卡和宿主机的物理网卡连接起来，因此，虚拟机能够发送和接收由物理网卡传输的数据包。这种方式叫做网络桥接。</p><p>下面将告诉你如何创建并且配置网桥，我们创建一个网桥称它为 br0。</p><p>首先，安装一个必需的包，然后用命令行创建一个网桥。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ sudo apt-get install bridge-utils</span></span>
<span class="line"><span>    $ sudo brctl addbr br0</span></span></code></pre></div>`,33)),n("p",null,[s[1]||(s[1]=a("下一步就是配置已经创建好的网桥，即修改位于 ",-1)),s[2]||(s[2]=n("code",null,"/etc/network/interfaces",-1)),s[3]||(s[3]=a(" 的配置文件。我们需要将该桥接网卡设置成开机启动。为了修改该配置文件，你需要关闭你的操作系统上的网络管理器（如果你在使用它的话）。跟随",-1)),e(i,{href:"http://xmodulo.com/disable-network-manager-linux.html"},{default:t(()=>[...s[0]||(s[0]=[a("操作指南",-1)])]),_:1}),s[4]||(s[4]=a("的说明去关闭网络管理器。",-1))]),s[19]||(s[19]=l(`<p>关闭网络管理器之后，接下来就是通过修改配置文件来配置网桥了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    #auto eth0</span></span>
<span class="line"><span>    #iface eth0 inet dhcp</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    auto br0</span></span>
<span class="line"><span>    iface br0 inet dhcp</span></span>
<span class="line"><span>            bridge_ports eth0</span></span>
<span class="line"><span>            bridge_stp off</span></span>
<span class="line"><span>            bridge_fd 0</span></span>
<span class="line"><span>            bridge_maxwait 0</span></span></code></pre></div><p>在上面的配置中，我假设 eth0 是主要网卡，它也是连接到外网的网卡，同样，我假设 eth0 将会通过 DHCP 协议自动获取 ip 地址。注意，之前在 <code>/etc/network/interfaces</code> 中还没有对 eth0 进行任何配置。桥接网卡 br0 引用了 eth0 的配置，而 eth0 也会受到 br0 的制约。</p><p>重启网络服务，并确认网桥已经被成功的配置好。如果成功的话，br0 的 ip 地址将会是 eth0 自动分配的 ip 地址，而且 eth0 不会被分配任何 ip 地址。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ sudo /etc/init.d/networking restart</span></span>
<span class="line"><span>    $ ifconfig</span></span></code></pre></div><p>如果因为某些原因，eth0 仍然保留了之前分配给了 br0 的 ip 地址，那么你可能必须手动删除 eth0 的 ip 地址。</p><p><img src="https://c2.staticflickr.com/2/1698/23780708850_66cd7ba6ea_c.jpg" alt=""></p><h3 id="第四步-用命令行创建一个虚拟机" tabindex="-1">第四步：用命令行创建一个虚拟机 <a class="header-anchor" href="#第四步-用命令行创建一个虚拟机" aria-label="Permalink to “第四步：用命令行创建一个虚拟机”">​</a></h3><p>对于虚拟机来说，它的配置信息被存储在它对应的xml文件中。因此，创建一个虚拟机的第一步就是准备一个与虚拟机对应的 xml 文件。</p><p>下面是一个示例 xml 文件，你可以根据需要手动修改它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    &lt;domain type=&#39;kvm&#39;&gt;</span></span>
<span class="line"><span>      &lt;name&gt;alice&lt;/name&gt;</span></span>
<span class="line"><span>      &lt;uuid&gt;f5b8c05b-9c7a-3211-49b9-2bd635f7e2aa&lt;/uuid&gt;</span></span>
<span class="line"><span>      &lt;memory&gt;1048576&lt;/memory&gt;</span></span>
<span class="line"><span>      &lt;currentMemory&gt;1048576&lt;/currentMemory&gt;</span></span>
<span class="line"><span>      &lt;vcpu&gt;1&lt;/vcpu&gt;</span></span>
<span class="line"><span>      &lt;os&gt;</span></span>
<span class="line"><span>        &lt;type&gt;hvm&lt;/type&gt;</span></span>
<span class="line"><span>        &lt;boot dev=&#39;cdrom&#39;/&gt;</span></span>
<span class="line"><span>      &lt;/os&gt;</span></span>
<span class="line"><span>      &lt;features&gt;</span></span>
<span class="line"><span>        &lt;acpi/&gt;</span></span>
<span class="line"><span>      &lt;/features&gt;</span></span>
<span class="line"><span>      &lt;clock offset=&#39;utc&#39;/&gt;</span></span>
<span class="line"><span>      &lt;on_poweroff&gt;destroy&lt;/on_poweroff&gt;</span></span>
<span class="line"><span>      &lt;on_reboot&gt;restart&lt;/on_reboot&gt;</span></span>
<span class="line"><span>      &lt;on_crash&gt;destroy&lt;/on_crash&gt;</span></span>
<span class="line"><span>      &lt;devices&gt;</span></span>
<span class="line"><span>        &lt;emulator&gt;/usr/bin/kvm&lt;/emulator&gt;</span></span>
<span class="line"><span>        &lt;disk type=&quot;file&quot; device=&quot;disk&quot;&gt;</span></span>
<span class="line"><span>          &lt;driver name=&quot;qemu&quot; type=&quot;raw&quot;/&gt;</span></span>
<span class="line"><span>          &lt;source file=&quot;/home/dev/images/alice.img&quot;/&gt;</span></span>
<span class="line"><span>          &lt;target dev=&quot;vda&quot; bus=&quot;virtio&quot;/&gt;</span></span>
<span class="line"><span>          &lt;address type=&quot;pci&quot; domain=&quot;0x0000&quot; bus=&quot;0x00&quot; slot=&quot;0x04&quot; function=&quot;0x0&quot;/&gt;</span></span>
<span class="line"><span>        &lt;/disk&gt;</span></span>
<span class="line"><span>        &lt;disk type=&quot;file&quot; device=&quot;cdrom&quot;&gt;</span></span>
<span class="line"><span>          &lt;driver name=&quot;qemu&quot; type=&quot;raw&quot;/&gt;</span></span>
<span class="line"><span>          &lt;source file=&quot;/home/dev/iso/CentOS-6.5-x86_64-minimal.iso&quot;/&gt;</span></span>
<span class="line"><span>          &lt;target dev=&quot;hdc&quot; bus=&quot;ide&quot;/&gt;</span></span>
<span class="line"><span>          &lt;readonly/&gt;</span></span>
<span class="line"><span>          &lt;address type=&quot;drive&quot; controller=&quot;0&quot; bus=&quot;1&quot; target=&quot;0&quot; unit=&quot;0&quot;/&gt;</span></span>
<span class="line"><span>        &lt;/disk&gt;</span></span>
<span class="line"><span>        &lt;interface type=&#39;bridge&#39;&gt;</span></span>
<span class="line"><span>          &lt;source bridge=&#39;br0&#39;/&gt;</span></span>
<span class="line"><span>          &lt;mac address=&quot;00:00:A3:B0:56:10&quot;/&gt;</span></span>
<span class="line"><span>        &lt;/interface&gt;</span></span>
<span class="line"><span>        &lt;controller type=&quot;ide&quot; index=&quot;0&quot;&gt;</span></span>
<span class="line"><span>          &lt;address type=&quot;pci&quot; domain=&quot;0x0000&quot; bus=&quot;0x00&quot; slot=&quot;0x01&quot; function=&quot;0x1&quot;/&gt;</span></span>
<span class="line"><span>        &lt;/controller&gt;</span></span>
<span class="line"><span>        &lt;input type=&#39;mouse&#39; bus=&#39;ps2&#39;/&gt;</span></span>
<span class="line"><span>        &lt;graphics type=&#39;vnc&#39; port=&#39;-1&#39; autoport=&quot;yes&quot; listen=&#39;0.0.0.0&#39;/&gt;</span></span>
<span class="line"><span>        &lt;console type=&#39;pty&#39;&gt;</span></span>
<span class="line"><span>          &lt;target port=&#39;0&#39;/&gt;</span></span>
<span class="line"><span>        &lt;/console&gt;</span></span>
<span class="line"><span>      &lt;/devices&gt;</span></span>
<span class="line"><span>    &lt;/domain&gt;</span></span></code></pre></div><p>上面的主机xml配置文件定义了如下的虚拟机内容。</p><ul><li><p>1GB内存，一个虚拟cpu和一个硬件驱动</p></li><li><p>磁盘镜像：<code>/home/dev/images/alice.img</code></p></li><li><p>从 CD-ROM 引导（<code>/home/dev/iso/CentOS-6.5-x86_64-minomal.iso</code>）</p></li><li><p>网络：一个桥接到 br0 的虚拟网卡</p></li><li><p>通过 VNC 远程访问</p></li></ul><p><code>&lt;uuid&gt;&lt;/uuid&gt;</code> 中的 UUID 字符串可以随机生成。为了得到一个随机的 uuid 字符串，你可能需要使用 uuid 命令行工具。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ sudo apt-get install uuid</span></span>
<span class="line"><span>    $ uuid</span></span></code></pre></div><p>生成一个主机 xml 配置文件的方式就是通过一个已经存在的虚拟机来导出它的 xml 配置文件。如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh dumpxml alice &gt; bob.xml</span></span></code></pre></div><p><img src="https://c2.staticflickr.com/6/5808/23968234602_25e8019ec8_c.jpg" alt=""></p><h3 id="第五步-使用命令行启动虚拟机" tabindex="-1">第五步：使用命令行启动虚拟机 <a class="header-anchor" href="#第五步-使用命令行启动虚拟机" aria-label="Permalink to “第五步：使用命令行启动虚拟机”">​</a></h3><p>在启动虚拟机之前，我们需要创建它的初始磁盘镜像。为此，你需要使用 qemu-img 命令来生成一个 qemu-kvm 镜像。下面的命令将会创建 10 GB 大小的空磁盘，并且它是 qcow2 格式的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ qemu-img create -f qcow2 /home/dev/images/alice.img 10G</span></span></code></pre></div><p>使用 qcow2 格式的磁盘镜像的好处就是它在创建之初并不会给它分配全部大小磁盘容量（这里是 10 GB），而是随着虚拟机中文件的增加而逐渐增大。因此，它对空间的使用更加有效。</p><p>现在，你可以通过使用之前创建的 xml 配置文件启动你的虚拟机了。下面的命令将会创建一个虚拟机，然后自动启动它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh create alice.xml</span></span>
<span class="line"><span>    Domain alice created from alice.xml</span></span></code></pre></div><p><strong>注意</strong>: 如果你对一个已经存在的虚拟机执行了了上面的命令，那么这个操作将会在没有任何警告的情况下抹去那个已经存在的虚拟机的全部信息。如果你已经创建了一个虚拟机，你可能会使用下面的命令来启动虚拟机。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh start alice.xml</span></span></code></pre></div><p>使用如下命令确认一个新的虚拟机已经被创建并成功的被启动。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh list</span></span></code></pre></div><pre><code> Id    Name                           State
----------------------------------------------------
 3     alice                          running
</code></pre><p>同样，使用如下命令确认你的虚拟机的虚拟网卡已经被成功的添加到了你先前创建的 br0 网桥中。</p><pre><code>$ sudo brctl show
</code></pre><p><img src="https://c2.staticflickr.com/2/1546/23449585383_a371e9e579_c.jpg" alt=""></p><h3 id="远程连接虚拟机" tabindex="-1">远程连接虚拟机 <a class="header-anchor" href="#远程连接虚拟机" aria-label="Permalink to “远程连接虚拟机”">​</a></h3><p>为了远程访问一个正在运行的虚拟机的控制台，你可以使用VNC客户端。</p><p>首先，你需要使用如下命令找出用于虚拟机的VNC端口号。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ sudo netstat -nap | egrep &#39;(kvm|qemu)&#39;</span></span></code></pre></div><p><img src="https://c2.staticflickr.com/6/5633/23448144274_49045bc868_c.jpg" alt=""></p><p>在这个例子中，用于 alice 虚拟机的 VNC 端口号是 5900。 然后启动一个VNC客户端，连接到一个端口号为5900的VNC服务器。在我们的例子中，虚拟机支持由CentOS光盘文件启动。</p><p><img src="https://c2.staticflickr.com/2/1533/24076369675_99408972a4_c.jpg" alt=""></p><h3 id="使用-virsh-管理虚拟机" tabindex="-1">使用 virsh 管理虚拟机 <a class="header-anchor" href="#使用-virsh-管理虚拟机" aria-label="Permalink to “使用 virsh 管理虚拟机”">​</a></h3><p>下面列出了 virsh 命令的常规用法：</p><p>创建客户机并且启动虚拟机：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh create alice.xml</span></span></code></pre></div><p>停止虚拟机并且删除客户机：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh destroy alice</span></span></code></pre></div><p>关闭虚拟机（不用删除它）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh shutdown alice</span></span></code></pre></div><p>暂停虚拟机：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh suspend alice</span></span></code></pre></div><p>恢复虚拟机：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh resume alice</span></span></code></pre></div><p>访问正在运行的虚拟机的控制台：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh console alice</span></span></code></pre></div><p>设置虚拟机开机启动：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh autostart alice</span></span></code></pre></div><p>查看虚拟机的详细信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh dominfo alice</span></span></code></pre></div><p>编辑虚拟机的配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh edit alice</span></span></code></pre></div><p>上面的这个命令将会使用一个默认的编辑器来调用主机配置文件。该配置文件中的任何改变都将自动被libvirt验证其正确性。</p><p>你也可以在一个virsh会话中管理虚拟机。下面的命令会创建并进入到一个virsh会话中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh</span></span></code></pre></div><p>在 virsh 提示中，你可以使用任何 virsh 命令。</p><p><img src="https://c2.staticflickr.com/6/5645/23708565129_b1ef968b30_c.jpg" alt=""></p><h3 id="问题处理" tabindex="-1">问题处理 <a class="header-anchor" href="#问题处理" aria-label="Permalink to “问题处理”">​</a></h3><ol><li><p>我在创建虚拟机的时候遇到了一个错误：</p><p>error: internal error: no supported architecture for os type &#39;hvm&#39;</p></li></ol><p>如果你的硬件不支持虚拟化的话你可能就会遇到这个错误。（例如，Intel VT或者AMD-V），这是运行KVM所必需的。如果你遇到了这个错误，而你的cpu支持虚拟化，那么这里可以给你一些可用的解决方案：</p><p>首先，检查你的内核模块是否丢失。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  $ lsmod | grep kvm</span></span></code></pre></div><p>如果内核模块没有加载，你必须按照如下方式加载它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  $ sudo modprobe kvm_intel (for Intel processor)</span></span>
<span class="line"><span>  $ sudo modprobe kvm_amd (for AMD processor)</span></span></code></pre></div><p>第二个解决方案就是添加 <code>--connect qemu:///system</code> 参数到 <code>virsh</code> 命令中，如下所示。当你正在你的硬件平台上使用超过一个虚拟机管理器的时候就需要添加这个参数（例如，VirtualBox，VMware）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  $ virsh --connect qemu:///system create alice.xml</span></span></code></pre></div><ol start="2"><li>当我试着访问我的虚拟机的登陆控制台的时候遇到了错误：</li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>   $ virsh console alice</span></span>
<span class="line"><span>   error: internal error: cannot find character device &lt;null&gt;</span></span></code></pre></div><p>这个错误发生的原因是你没有在你的虚拟机配置文件中定义控制台设备。在 xml 文件中加上下面的内部设备部分即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  &lt;console type=&#39;pty&#39;&gt;</span></span>
<span class="line"><span>    &lt;target port=&#39;0&#39;/&gt;</span></span>
<span class="line"><span>  &lt;/console&gt;</span></span></code></pre></div><hr>`,78)),n("p",null,[s[6]||(s[6]=a("via: ",-1)),e(i,{href:"http://xmodulo.com/use-kvm-command-line-debian-ubuntu.html"},{default:t(()=>[...s[5]||(s[5]=[a("http://xmodulo.com/use-kvm-command-line-debian-ubuntu.html",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=a("作者：",-1)),e(i,{href:"http://xmodulo.com/author/nanni"},{default:t(()=>[...s[7]||(s[7]=[a("Dan Nanni",-1)])]),_:1}),s[11]||(s[11]=a(" 译者：",-1)),e(i,{href:"https://github.com/kylepeng93"},{default:t(()=>[...s[8]||(s[8]=[a("kylepeng93",-1)])]),_:1}),s[12]||(s[12]=a(" 校对：",-1)),e(i,{href:"https://github.com/oska874"},{default:t(()=>[...s[9]||(s[9]=[a("Ezio",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...s[14]||(s[14]=[a("Linux中国",-1)])]),_:1}),s[17]||(s[17]=a(" 荣誉推出",-1))])])}const C=p(h,[["render",c]]);export{y as __pageData,C as default};
